        version,
        dependency_id,
        dependency_version,
        &root_archive_cid,
        &dependency_archive_cid,
        &capsule,
    )?;
    receipt::verify(store, &receipt_cid)?;
    Ok(Built {
        capsule,
        root_archive_cid,
        dependency_archive_cid,
        receipt_cid,
    })
}

